 {Bytes ram=base_ram("");put(ram,NODE+0xa9,1,0x40);State s=st(0x206a4);reject(ram,s,0x206c0,"missing or ambiguous physical program bus ROM byte");}   // index 100: 207d4 (not 206d4)
